import { test } from 'node:test';
import assert from 'node:assert/strict';
import { median } from './stats.js';

test('median of even-length array is mean of the two middle values', () => {
  assert.equal(median([1, 2, 3, 4]), 2.5);
});

test('median of even-length unsorted array', () => {
  assert.equal(median([4, 1, 3, 2]), 2.5);
  assert.equal(median([10, 2]), 6);
});

test('median of odd-length array is the middle value', () => {
  assert.equal(median([1, 2, 3]), 2);
  assert.equal(median([3, 1, 2]), 2);
  assert.equal(median([7]), 7);
});

test('median does not mutate its input', () => {
  const input = [3, 1, 2, 4];
  median(input);
  assert.deepEqual(input, [3, 1, 2, 4]);
});

